// Node 10 · Normalise, recompute, and self-heal
// The model may READ numbers. It never CALCULATES them - and where the
// document contradicts itself, arithmetic wins over the model.
const cfg     = $('02 · Config').first().json;
const gmail   = $('01 · Receive order email').first().json;
const pdfText = $('07 · Extract PDF text').first().json.text || '';

const method = pdfText.length >= Number(cfg.textThreshold) ? 'text' : 'vision';

let sourcePdfUrl = null;
try { sourcePdfUrl = $('06 · Archive PDF to Drive').first().json.webViewLink ?? null; } catch (e) {}

const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const num    = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
const near   = (a, b) => a !== null && b !== null && Math.abs(a - b) <= 0.05;

const results = [];

for (const item of $input.all()) {
  let src = item.json.output ?? item.json;
  let parse_ok = true;
  if (typeof item.json.response === 'string') {
    try { src = JSON.parse(item.json.response); } catch (e) { src = {}; parse_ok = false; }
  }
  if (!src || typeof src !== 'object') { src = {}; parse_ok = false; }

  const lines = (src.line_items ?? []).map((l, i) => {
    const unit    = round2(num(l.unit_price) ?? 0);
    const printed = num(l.line_total);
    let   qty     = num(l.qty) ?? 0;

    let qty_read      = qty;
    let qty_corrected = false;

    // Self-heal: if qty x unit disagrees with the printed line total, and the
    // printed total divides cleanly by the unit price, trust the arithmetic.
    if (printed !== null && unit > 0 && !near(round2(qty * unit), printed)) {
      const implied = printed / unit;
      const rounded = Math.round(implied);
      if (rounded > 0 && Math.abs(implied - rounded) < 0.001) {
        qty = rounded;
        qty_corrected = true;
      }
    }

    const computed = round2(qty * unit);
    return {
      line_no: i + 1,
      sku: String(l.sku ?? '').trim().toUpperCase(),
      description: String(l.description ?? '').trim(),
      qty,
      qty_read,
      qty_corrected,
      unit_price: unit,
      line_total: computed,
      printed_line_total: printed,
      line_total_matches: printed === null ? null : near(computed, printed),
    };
  });

  const computed_subtotal = round2(lines.reduce((s, l) => s + l.line_total, 0));
  const computed_vat      = round2(computed_subtotal * Number(cfg.vatRate));
  const computed_total    = round2(computed_subtotal + computed_vat);

  const printed_subtotal = num(src.printed_subtotal);
  const printed_vat      = num(src.printed_vat);
  const printed_total    = num(src.printed_total);

  const po = (src.po_number ?? '').toString().trim();
  const corrections = lines.filter((l) => l.qty_corrected).length;

  results.push({
    json: {
      order_id: po || `TMP-${gmail.id}`,
      gmail_message_id: gmail.id,
      po_number: po || null,
      order_date: src.order_date ?? null,
      required_by: src.required_by ?? null,
      customer_name: (src.customer_name ?? '').toString().trim() || null,
      customer_vat: (src.customer_vat ?? '').toString().trim() || null,
      currency: src.currency || cfg.currency,

      lines,
      line_count: lines.length,

      computed_subtotal,
      computed_vat,
      computed_total,
      printed_subtotal,
      printed_vat,
      printed_total,

      subtotal_matches: near(printed_subtotal, computed_subtotal),
      total_matches:    near(printed_total, computed_total),
      totals_absent:    printed_subtotal === null && printed_total === null,
      lines_consistent: lines.every((l) => l.line_total_matches !== false),

      qty_corrections: corrections,
      self_healed: corrections > 0 && near(printed_subtotal, computed_subtotal),

      parse_ok,
      extraction_method: method,
      source_pdf_url: sourcePdfUrl,
      extracted_at: new Date().toISOString(),
    },
  });
}

return results;

const text = $input.first().json.text || '';

const prompt = `Extract purchase order data from the text below.
Return ONLY JSON: {"po_number":string|null,"order_date":string|null,"required_by":string|null,
"customer_name":string|null,"customer_vat":string|null,"currency":string,
"printed_subtotal":number|null,"printed_vat":number|null,"printed_total":number|null,
"line_items":[{"sku":string,"description":string,"qty":number,"unit_price":number,"line_total":number}]}

Rules: do NOT calculate anything; copy printed totals exactly or null. unit_price EXCLUDES VAT.
customer_name is the company that ISSUED the order (letterhead at top), NOT the supplier.

TEXT:
${text}`;

return [{
  json: {
    body: {
      model: 'gemma3:4b',
      prompt,
      stream: false,
      format: 'json',
      options: { temperature: 0, seed: 42, top_k: 1, num_predict: 800 },
    },
  },
}];

// Node 13 · Validation verdict
// Turns all the collected signals into one decision plus human-readable reasons.
const order     = $('10 · Normalise & recompute').first().json;
const customers = $('11 · Read customer master').all().map(i => i.json);
const prices    = $('12 · Read price list').all().map(i => i.json);

// Loose comparison: case, punctuation and spacing shouldn't decide a match.
const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const near = (a, b) => a != null && b != null && Math.abs(Number(a) - Number(b)) <= 0.01;

const reasons = [];   // blocking - these send the order to review
const notes   = [];   // informational - recorded, but not blocking

let totalsReconciled = false;   // did BOTH printed values agree with our arithmetic?

// --- did the model return anything usable at all? ---
if (order.parse_ok === false) reasons.push('Extraction returned unparseable output');

// --- required fields ---
if (!order.po_number)     reasons.push('No PO number on the document');
if (!order.order_date)    reasons.push('No order date');
if (!order.customer_name) reasons.push('No customer name');
if (!order.lines || order.lines.length === 0) reasons.push('No line items extracted');

// --- customer must exist in the master ---
let customer = customers.find(c => norm(c.company_name) === norm(order.customer_name));
if (!customer && order.customer_vat) {
  customer = customers.find(c => norm(c.vat_number) === norm(order.customer_vat));
  if (customer) notes.push('Customer matched on VAT number, not name');
}
if (!customer) {
  reasons.push(`Customer not in master: "${order.customer_name ?? 'unknown'}"`);
}

// --- every SKU must exist, and its price must match the price list ---
const byIdx = new Map(prices.map(p => [String(p.sku).trim().toUpperCase(), p]));
const lines = (order.lines ?? []).map((l) => {
  const master = byIdx.get(l.sku);
  const master_price = master ? Number(master.unit_price_excl_vat) : null;
  const price_matches = master ? near(l.unit_price, master_price) : null;

  if (!master) {
    reasons.push(`Line ${l.line_no}: SKU not in price list (${l.sku || 'blank'})`);
  } else if (!price_matches) {
    reasons.push(
      `Line ${l.line_no} (${l.sku}): price R${l.unit_price} does not match price list R${master_price}`
    );
  }
  if (l.line_total_matches === false) {
    reasons.push(`Line ${l.line_no} (${l.sku}): qty x price does not equal the printed line total`);
  }
  if (l.qty_corrected) {
    notes.push(`Line ${l.line_no}: quantity corrected from ${l.qty_read} to ${l.qty} by arithmetic`);
  }

  return { ...l, master_price, price_matches, master_description: master?.description ?? null };
});

// --- totals must agree with our own arithmetic, against BOTH printed values ---
// Sigma(lines) and the printed subtotal can be wrong together and still agree
// with each other. The printed grand total is a separate reading of the same
// fact, so it disagrees when they are. Checking only the subtotal is a blind spot.
if (order.totals_absent) {
  reasons.push('Document shows no totals to check against');
} else {
  if (order.subtotal_matches === false) {
    reasons.push(
      `Subtotal mismatch: document says R${order.printed_subtotal}, lines add to R${order.computed_subtotal}`
    );
  }

  const vatRate       = Number($('02 · Config').first().json.vatRate) || 0.15;
  const computedSub   = Number(order.computed_subtotal);
  const computedTotal = Math.round(computedSub * (1 + vatRate) * 100) / 100;
  const printedTotal  = Number(order.printed_total);

  if (!Number.isFinite(computedSub)) {
    reasons.push('Could not compute a subtotal from the extracted lines');
  } else if (!Number.isFinite(printedTotal) || printedTotal <= 0) {
    notes.push('Document shows no grand total - only the subtotal could be cross-checked');
  } else if (Math.abs(computedTotal - printedTotal) > 0.02) {
    reasons.push(
      `Total mismatch: document says R${printedTotal.toFixed(2)}, ` +
      `our lines plus VAT come to R${computedTotal.toFixed(2)} ` +
      `(out by R${Math.abs(computedTotal - printedTotal).toFixed(2)})`
    );
  } else if (order.subtotal_matches !== false) {
    totalsReconciled = true;   // both independent printed values agree with us
  }
}

// --- scanned documents are never trusted on numbers alone ---
if (order.extraction_method === 'vision') {
  notes.push('Extracted from a scanned image - numbers are less reliable');
  const unmatched = lines.filter(l => l.price_matches !== true).length;
  if (unmatched > 0) {
    reasons.push(`Scanned order: ${unmatched} line(s) could not be confirmed against the price list`);
  }
}

const valid = reasons.length === 0;

return [{
  json: {
    ...order,
    lines,

    valid,
    status: valid ? 'registered' : 'needs_review',
    reasons,
    review_reasons: reasons.join(' | '),
    notes,
    note_text: notes.join(' | '),

    // Earned, not assumed: 'high' requires TWO independent printed values to agree.
    totals_reconciled: totalsReconciled,
    confidence: !valid ? 'low' : (totalsReconciled ? 'high' : 'medium'),

    // Enrichment the later stages need
    customer_code:  customer?.customer_code  ?? null,
    customer_email: customer?.email          ?? null,
    payment_terms:  customer?.payment_terms  ?? null,

    validated_at: new Date().toISOString(),
  },
}];

// 15a · Build Orders row - shape the item to match the sheet's columns exactly,
// so the Sheets node can map automatically instead of 25 manual field mappings.
const now = new Date().toISOString();

return $input.all().map((item) => {
  const o = item.json;

  // Honest confidence signal rather than a number the model made up.
  let confidence = 'high';
  if (o.extraction_method === 'vision') confidence = 'low';
  else if (o.qty_corrections > 0)       confidence = 'medium';

  return {
    json: {
      order_id:          o.order_id,
      gmail_message_id:  o.gmail_message_id,
      po_number:         o.po_number ?? '',
      order_date:        o.order_date ?? '',
      required_by:       o.required_by ?? '',
      customer_code:     o.customer_code ?? '',
      customer_name:     o.customer_name ?? '',
      customer_vat:      o.customer_vat ?? '',
      customer_email:    o.customer_email ?? '',
      currency:          o.currency ?? 'ZAR',
      subtotal_excl_vat: o.computed_subtotal,
      vat_amount:        o.computed_vat,
      total_incl_vat:    o.computed_total,
      printed_total:     o.printed_total ?? '',
      status:            o.status,
      source_pdf_url:    o.source_pdf_url ?? '',
      extraction_method: o.extraction_method,
      confidence,
      review_reasons:    o.review_reasons ?? '',
      invoice_number:    '',
      invoice_pdf_url:   '',
      approved_by:       '',
      approved_at:       '',
      created_at:        now,
      updated_at:        now,

      // kept for the next nodes, ignored by the sheet
      _lines: o.lines,
      _notes: o.note_text ?? '',
    },
  };
});

// 16 · Expand line items - one order becomes N line items.
// 15b is a Sheets node and replaced the item, so reach back to 15a for the lines.
const src = $('15a · Build Orders row').first().json;
const now = new Date().toISOString();

if (!src.order_id) {
  throw new Error('Cannot expand line items: order_id is empty on the 15a record.');
}

const lines = Array.isArray(src._lines) ? src._lines : [];

if (lines.length === 0) {
  // A needs_review record with nothing to expand is a legitimate outcome.
  // A record claiming to be registered with no lines is a data-integrity fault.
  if (src.status === 'registered') {
    throw new Error(
      `Order ${src.order_id} was registered with no line items. ` +
      `Check node 20 (correction merge) and node 09a-2 (extraction).`
    );
  }
  return [];
}

return lines.map((l) => ({
  json: {
    order_id:            src.order_id,
    line_no:             l.line_no,
    sku:                 l.sku,
    description:         l.description || l.master_description || '',
    qty:                 l.qty,
    unit_price_excl_vat: l.unit_price,
    line_total_excl_vat: l.line_total,
    sku_matched:         l.price_matches === true,
    created_at:          now,
    line_key:            `${src.order_id}-${l.line_no}`,
  },
}));

// 18a · Build review row - everything a human needs to fix this without
// opening the workflow or the original email.
const now = new Date().toISOString();

return $input.all().map((item) => {
  const o = item.json;

  // A compact snapshot of what was actually read, so the reviewer can see
  // the machine's version beside the document.
  const snapshot = {
    po_number: o.po_number,
    order_date: o.order_date,
    customer_name: o.customer_name,
    customer_vat: o.customer_vat,
    computed_subtotal: o.computed_subtotal,
    computed_vat: o.computed_vat,
    computed_total: o.computed_total,
    printed_subtotal: o.printed_subtotal,
    printed_total: o.printed_total,
    extraction_method: o.extraction_method,
    lines: (o.lines ?? []).map((l) => ({
      line_no: l.line_no,
      sku: l.sku,
      qty: l.qty,
      qty_read: l.qty_read,
      unit_price: l.unit_price,
      master_price: l.master_price,
      line_total: l.line_total,
    })),
  };

  return {
    json: {
      review_id:        `REV-${o.order_id}`,
      order_id:         o.order_id,
      gmail_message_id: o.gmail_message_id,
      po_number:        o.po_number ?? '',
      customer_name:    o.customer_name ?? '',
      reasons:          o.review_reasons ?? '',
      extracted_json:   JSON.stringify(snapshot),
      source_pdf_url:   o.source_pdf_url ?? '',
      status:           'open',
      raised_at:        now,
      resolved_at:      '',
      resolved_by:      '',
    },
  };
});

