// 20 · Merge correction - overlay the human's edits onto the extracted order,
// then RE-VALIDATE. A human answering one question is not evidence that the
// other answers are right, so nothing here asserts validity - it re-earns it.
const original = $('13 · Validation verdict').first().json;
const form     = $input.first().json.data ?? $input.first().json ?? {};

// Form field names vary by n8n version - accept either shape.
const pick = (k) => {
  const v = form[k] ?? form[k.replace('_', ' ')] ?? '';
  return String(v).trim();
};

const decision = (pick('decision') || 'Register').toLowerCase();
if (decision.startsWith('reject')) {
  return [{ json: { ...original, status: 'rejected', rejected_at: new Date().toISOString(),
                    reviewer_comments: pick('comments'), _rejected: true } }];
}

// Overlay: a blank answer means "keep what the machine read".
const merged = { ...original };
const po       = pick('po_number');
const customer = pick('customer_name');
if (po)       merged.po_number     = po;
if (customer) merged.customer_name = customer;
merged.order_id = merged.po_number || original.order_id;

// Re-check the blocking conditions. Only what a form answer could plausibly
// fix is re-tested; everything else keeps whatever node 13 decided.
const stillMissing = [];
if (!merged.po_number)     stillMissing.push('No PO number on the document');
if (!merged.order_date)    stillMissing.push('No order date');
if (!merged.customer_name) stillMissing.push('No customer name');
if (!Array.isArray(merged.lines) || merged.lines.length === 0) {
  stillMissing.push('No line items extracted');
}

const fixed = stillMissing.length === 0;

return [{
  json: {
    ...merged,
    status:  fixed ? 'registered' : 'needs_review',
    valid:   fixed,
    reasons: stillMissing,
    review_reasons: stillMissing.join(' | '),
    confidence: fixed ? 'medium' : 'low',   // human-touched is never 'high'
    reviewed_by: $('02 · Config').first().json.reviewerEmail,
    reviewed_at: new Date().toISOString(),
    reviewer_comments: pick('comments'),
    corrected_by_human: true,
  },
}];

// 22a · Build audit row - one line of history per execution, whichever path ran.
// A node reference throws if that node didn't execute in this run,
// which is how we tell the three paths apart.
const ran = (name) => { try { $(name).first(); return true; } catch (e) { return false; } };

let to_status = 'skipped_duplicate';
let detail    = 'Message already processed - labelled and stopped';
let order_id  = '';

if (ran('15b · Register order')) {
  const o = $('15a · Build Orders row').first().json;
  order_id  = o.order_id;
  to_status = 'registered';
  detail    = ran('20 · Merge correction')
    ? `Registered after human correction by ${$('20 · Merge correction').first().json.reviewed_by ?? 'reviewer'}`
    : `Registered automatically (${o.extraction_method}, confidence ${o.confidence})`;
} else if (ran('18b · Queue for review')) {
  const r = $('18a · Build review row').first().json;
  order_id  = r.order_id;
  to_status = 'needs_review';
  detail    = r.reasons;
}

return [{
  json: {
    timestamp:    new Date().toISOString(),
    workflow:     '01 · Order Intake & Validation',
    execution_id: $execution.id,
    order_id,
    from_status:  'received',
    to_status,
    node:         '22 · Audit log',
    detail,
  },
}];

// 09b-3 · Same schema and same settings as the text branch.
// The ONLY difference between the two branches is this images array.
const jpeg = $input.first().json.jpeg_base64;

const prompt = `Extract the purchase order data from this document image.
Return ONLY JSON: {"po_number":string|null,"order_date":string|null,"required_by":string|null,
"customer_name":string|null,"customer_vat":string|null,"currency":string,
"printed_subtotal":number|null,"printed_vat":number|null,"printed_total":number|null,
"line_items":[{"sku":string,"description":string,"qty":number,"unit_price":number,"line_total":number}]}

Rules: do NOT calculate anything; copy printed totals exactly or null. unit_price EXCLUDES VAT.
customer_name is the company that ISSUED the order (letterhead at top), NOT the supplier.
A space is a thousands separator: "8 424.00" is 8424.00.`;

return [{
  json: {
    body: {
      model: 'gemma3:4b',
      prompt,
      images: [jpeg],
      stream: false,
      format: 'json',
      options: { temperature: 0, seed: 42, top_k: 1, num_predict: 900 },
    },
  },
}];
